impl WaapiClient {
    /// Chained namespace access starting at `ak`.
    pub fn ak(&mut self) -> AkClient<'_> {
        AkClient { client: self }
    }

    /// Shortcut for `client.ak().wwise()`.
    pub fn wwise(&mut self) -> WwiseClient<'_> {
        WwiseClient { client: self }
    }

    /// Shortcut for `client.ak().soundengine()`.
    pub fn soundengine(&mut self) -> SoundengineClient<'_> {
        SoundengineClient { client: self }
    }
}
